@startuml

class SoberCab {
  + licensePlate : string
  + model : string
  + capacity : int
}

class SoberCar {
  + ownerName : string
  + ownerPhone : string
  + ownerEmail : string
}

class RideHail {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + duration : float
  + distance : float
  + passengerCount : int
  + fee : float
  + requestType : RequestType
}

class RideShare {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + duration : float
  + distance : float
  + negotiatedFee : float
}

class Customer {
  + name : string
  + phoneNumber : string
}

class Accident {
  + date : date
  + location : string
  + damageAmount : float
}

enum RequestType {
  SoberApp
  HandWaving
}

SoberCab --|> SoberCar
SoberCar "1" *-- "1" SoberCab
SoberCar "1" o-- "0..*" Customer
RideHail "1" -- "1" SoberCab
RideShare "1" -- "1" SoberCab
RideHail "1" -- "1..*" Customer
RideShare "1" -- "1..*" Customer
SoberCab "1" -- "0..*" Accident
@enduml

